/* Access Suite offline service worker. Generated by scripts/assemble-site.mjs. */
const VERSION = '__VERSION__';
const FILES = __FILES__;
const CACHE = `access-suite-${VERSION}`;
const NAV_TIMEOUT_MS = 3000;

const abs = (path) => new URL(path, self.registration.scope).href;

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((cache) => cache.addAll(FILES.map(abs)))
      .then(() => self.skipWaiting()),
  );
});

// A tablet can keep a tool open for days. A page from an older version still
// asks for that version's files (such as the AI code, which loads on first
// use), and after a deploy they are gone from the server. So keep the last
// few versions' caches instead of deleting them all on activate.
const KEEP_PREVIOUS = 2;

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => {
        // CacheStorage lists caches oldest first.
        const older = keys.filter((k) => k.startsWith('access-suite-') && k !== CACHE);
        const stale = older.slice(0, Math.max(0, older.length - KEEP_PREVIOUS));
        return Promise.all(stale.map((k) => caches.delete(k)));
      })
      .then(() => self.clients.claim()),
  );
});

// Module scripts are fetched with an Origin header and servers often reply
// `Vary: Origin`; precached entries were stored without one, so ignore Vary
// (safe here: every asset URL is content-hashed and same-origin).
const MATCH = { ignoreSearch: true, ignoreVary: true };

function lookup(store, request) {
  return store.match(request, MATCH).then((hit) => {
    if (hit) return hit;
    // "/phrase-board" and "/phrase-board/" both mean its index.html.
    const url = new URL(request.url);
    const dir = url.pathname.endsWith('/') ? url.pathname : `${url.pathname}/`;
    return store.match(new URL(`${dir}index.html`, url.origin).href, MATCH);
  });
}

// This version first, so pages come from the newest build; then older
// versions, which may still hold files an open page asks for.
function fromCache(request) {
  return caches
    .open(CACHE)
    .then((cache) => lookup(cache, request))
    .then((hit) => hit || lookup(caches, request));
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  // Never touch other origins (AI providers, speech services): straight to network.
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    // Pages: fresh when the network answers quickly, otherwise the cached copy.
    event.respondWith(
      new Promise((resolve) => {
        let settled = false;
        const fallback = () => {
          if (settled) return;
          settled = true;
          fromCache(request).then((hit) => resolve(hit || fetch(request)));
        };
        const timer = setTimeout(fallback, NAV_TIMEOUT_MS);
        fetch(request)
          .then((res) => {
            if (settled) return;
            if (!res.ok) return fallback();
            settled = true;
            clearTimeout(timer);
            const copy = res.clone();
            caches.open(CACHE).then((c) => c.put(request, copy));
            resolve(res);
          })
          .catch(fallback);
      }),
    );
    return;
  }

  // Assets are content-hashed: cache first.
  event.respondWith(fromCache(request).then((hit) => hit || fetch(request)));
});
